package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user and an amount with up to two decimals,
 *  above 0.00. */
public class ValidateSplit {
    public void validate(@RequestBody SplitRequest request, Out<SplitInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (!amount.matches("\\d{1,12}(\\.\\d{1,2})?")) {
            throw new InvalidClaimException("The amount to split off must be a number with up to two decimals.");
        }
        BigDecimal value = new BigDecimal(amount).setScale(2);
        if (value.signum() <= 0) {
            throw new InvalidClaimException("The amount to split off must be more than 0.00.");
        }
        body.set(new SplitInput(request.user().trim(), value));
    }
}
package net.officefloor.hq.app.claim;

import java.util.List;
import net.officefloor.hq.app.holiday.HolidayRepository;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Split an amount off the loaded claim: only an OPEN claim not deferred on the sheet's today, and only an amount
 *  less than the claim's. The claim keeps the rest of its amount and loses any figure a statement bound it to; a new
 *  OPEN claim with the split-off amount, the same person, date and note, the next number, opened by the user, its
 *  terms fixed now from the terms in force on the sheet's today (as a new claim's is) and the claim's number as its
 *  split-from is stored (a late entry when that due-by is inside a soft-closed period), its OPEN line starting its status log. A split another user's change got to first is
 *  refused. */
public class SaveSplit {
    public void save(@Val SplitInput input, @Val Claim loaded, SheetRepository sheets, SettingRepository settings,
            HolidayRepository holidays, PersonRepository people, PeriodRepository periods, ClaimRepository repository, ClaimLogRepository log, Out<Split> split,
            Out<ClaimResponse> saved) throws ClaimStatusNotAllowedException, InvalidClaimException {
        if (loaded.status() != ClaimStatus.OPEN) {
            throw new ClaimStatusNotAllowedException("A " + loaded.status()
                    + " claim cannot be split; only an OPEN one can.");
        }
