        ClaimStatus to = switch (action) {
            case "open", "reject", "review" -> ClaimStatus.OPEN;
            case "settle", "approve", "resettle" -> ClaimStatus.SETTLED;
            case "void" -> ClaimStatus.VOID;
            case "delete" -> ClaimStatus.DELETED;
            case "restore" -> ClaimStatus.DRAFT;
            default -> throw new InvalidClaimException("Unknown claim action: " + action + ".");
        };
        String reason = null;
        if (action.equals("reject")) {
            reason = request.reason() == null ? "" : request.reason().trim();
            if (reason.isEmpty()) {
                throw new InvalidClaimException("Give a reason to reject a claim.");
            }
        } else if (action.equals("void") && request.reason() != null && !request.reason().isBlank()) {
            reason = request.reason().trim();
        }
        body.set(new ClaimStatusInput(request.user().trim(), action, to, reason));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Val;

/** Record the stored status change in the audit file, with the amount and date as the screen shows them,
 *  and the claim's number (for a void, the number it had); a settle or approve adds the due it fixed
 *  (n/a when the grade had no rate), a reject its reason, a void of a SETTLED claim reversed=<the frozen figure it had>. A settle, approve or re-settle that left it SETTLED
 *  is followed by one NOTIFY line per user watching its person, in the order they started watching. A settle that left the claim PENDING is CLAIM_PENDING. */
public class AuditClaimStatus {
    public void audit(@Val ClaimStatusInput input, @Val Claim loaded, @Val ClaimResponse saved,
            PersonRepository people, WatchRepository watches, Audit audit) {
        ClaimStatusChange.audit(input, loaded, saved, people, watches, audit);
    }
}
package net.officefloor.hq.app.rollup;

import net.officefloor.hq.app.claim.ClaimStatusInput;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Record, after the change's own lines, how the sheet's figures moved over it. */
public class AuditClaimStatusRollup {
    public void audit(@PathVariable("sheetId") String sheetId, @Val ClaimStatusInput request, @Val Rollup before,
            Rollups rollups) {
        rollups.record(sheetId.trim(), request.user(), before);
    }
}

