        BulkSettleResponse refused = new BulkSettleResponse(0, input.claimIds().size());
        if (sheets.archived(sheet)) {
            result.set(refused);
            return;
        }
        List<Claim> selected = new ArrayList<>();
        for (Person person : people.list(sheet)) {
